-- New products migrated from Shopify (previously missing from the new catalog)
insert into public.products (id, section, name, subtitle, price, compare_at, image, image2, images, story, material, suited_for, active)
values
  ('rakhi-set-pack-3', 'kids', 'Handmade Rakhi Set (Pack of 3)', 'Pack of 3 · Raksha Bandhan', 299, NULL, 'https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=533', 'https://lattutop.com/cdn/shop/files/8026f51851c9634619557f5660e7158f444ab63321b95977a0db16b9e36a86d6.png?v=1786720373&width=533', ARRAY['https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=900', 'https://lattutop.com/cdn/shop/files/8026f51851c9634619557f5660e7158f444ab63321b95977a0db16b9e36a86d6.png?v=1786720373&width=900'], 'Raksha Bandhan is a celebration of the bond between siblings — a thread tied not for its thread count, but for what it promises: protection, love, and a reason to come home. Each rakhi in this set is handcrafted, so no two are quite alike.', 'Premium threads and decorative embellishments, pack of 3', '{}', true),
  ('ganesha-rakhi-set', 'kids', 'Rakshabandhan Special: Ganesha Wooden Peg Dolls with Rakhi Set', '3–9 years · Rakhi Edition', 899, NULL, 'https://lattutop.com/cdn/shop/files/803f8bea6c2df733f5dcd41ff8e7770912f53235e86354399728279d9d5d124f.png?v=1786720427&width=533', 'https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=533', ARRAY['https://lattutop.com/cdn/shop/files/803f8bea6c2df733f5dcd41ff8e7770912f53235e86354399728279d9d5d124f.png?v=1786720427&width=900', 'https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=900', 'https://lattutop.com/cdn/shop/files/8026f51851c9634619557f5660e7158f444ab63321b95977a0db16b9e36a86d6.png?v=1786720373&width=900'], 'A Raksha Bandhan edition of the Ganesha Combo — the same hand-painted Ganesha, Shiva, and Parvati peg dolls, now paired with three festive rakhis, so the ritual of tying a thread comes with a story to tell alongside it.', 'Hand-painted wood, 3 rakhis included', '{}', true),
  ('krishna-radha-sudama-rakhi-set', 'kids', 'Rakshabandhan Special: Krishna, Radha, Sudama Wooden Peg Dolls with Rakhi Set', '3–9 years · Rakhi Edition', 799, NULL, 'https://lattutop.com/cdn/shop/files/Sqaure_Krishna.png?v=1786433803&width=533', 'https://lattutop.com/cdn/shop/files/ChatGPT_Image_Aug_11_2026_12_36_05_PM.png?v=1786433873&width=533', ARRAY['https://lattutop.com/cdn/shop/files/Sqaure_Krishna.png?v=1786433803&width=900', 'https://lattutop.com/cdn/shop/files/ChatGPT_Image_Aug_11_2026_12_36_05_PM.png?v=1786433873&width=900'], 'A Raksha Bandhan edition of the Krishna Radha Sudama set — the same peg dolls built around a story of friendship that asks nothing in return, now paired with three festive rakhis for the season of siblings.', 'Hand-painted wood, 3 rakhis included', '{}', true),
  ('ramayana-rakhi-set', 'kids', 'Rakshabandhan Special: Ramayana Wooden Peg Dolls with Rakhi Set', '3–9 years · Rakhi Edition', 1199, NULL, 'https://lattutop.com/cdn/shop/files/ChatGPT_Image_Aug_15_2026_01_03_25_AM.png?v=1786736075&width=533', 'https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=533', ARRAY['https://lattutop.com/cdn/shop/files/ChatGPT_Image_Aug_15_2026_01_03_25_AM.png?v=1786736075&width=900', 'https://lattutop.com/cdn/shop/files/88d58abb2570a9fa842fb15a90f7daa1121a3be871158dfb477f1d904ce55b14_2.png?v=1786719649&width=900', 'https://lattutop.com/cdn/shop/files/8026f51851c9634619557f5660e7158f444ab63321b95977a0db16b9e36a86d6.png?v=1786720373&width=900'], 'A Raksha Bandhan edition of the Ramayana Dolls Combo — Rama, Sita, Laxman, and Hanuman, now paired with three festive rakhis, for a gift that carries an epic and a tradition in the same box.', 'Hand-painted wood, 3 rakhis included', '{}', true),
  ('coder-collectible', 'collectible', 'Coder Wooden Collectible', 'Tech Icon', 799, NULL, 'https://lattutop.com/cdn/shop/files/2_001ce225-8aa9-4e27-9773-04b827d63e49.png?v=1745931001&width=533', 'https://lattutop.com/cdn/shop/files/3_7796a731-7b91-4d4b-883a-0627e3346852.png?v=1745931000&width=533', ARRAY['https://lattutop.com/cdn/shop/files/2_001ce225-8aa9-4e27-9773-04b827d63e49.png?v=1745931001&width=900', 'https://lattutop.com/cdn/shop/files/3_7796a731-7b91-4d4b-883a-0627e3346852.png?v=1745931000&width=900', 'https://lattutop.com/cdn/shop/files/4_665c4c3b-356e-41d0-b453-14668abe5ba8.png?v=1745931001&width=900', 'https://lattutop.com/cdn/shop/files/5_657da9c5-42e6-48a5-887a-44420a77334b.png?v=1745931000&width=900'], 'A desk companion for the ones who speak in semicolons — glasses on, hoodie zipped, ready to ship. For any coder, tech lead, or startup desk that needs a little personality.', 'Hand-painted wood', ARRAY['Work Desk', 'Gifting', 'Fan Collection'], true),
  ('kalam-collectible', 'collectible', 'Kalam Wooden Collectible', 'Science Icon', 799, NULL, 'https://lattutop.com/cdn/shop/files/1_f2a1af90-9e61-468d-ac46-a4671878f3ea.png?v=1773903259&width=533', 'https://lattutop.com/cdn/shop/files/2_65a99955-1b7b-41d7-9bce-a8f8d933f193.png?v=1773903259&width=533', ARRAY['https://lattutop.com/cdn/shop/files/1_f2a1af90-9e61-468d-ac46-a4671878f3ea.png?v=1773903259&width=900', 'https://lattutop.com/cdn/shop/files/2_65a99955-1b7b-41d7-9bce-a8f8d933f193.png?v=1773903259&width=900'], 'A tribute to Dr. APJ Abdul Kalam — India''s Missile Man and a President remembered as much for his humility as his achievements. For anyone who needs a daily reminder that curiosity and discipline go a long way.', 'Hand-painted wood', ARRAY['Work Desk', 'Gifting', 'Fan Collection'], true),
  ('spidey-collectible', 'collectible', 'Spidey Wooden Collectible', 'Pre-Book · Limited to 10 pieces', 1999, NULL, 'https://lattutop.com/cdn/shop/files/FRONT_d89edfe9-6f6c-469b-a0ac-b54b402e1141.png?v=1785678687&width=533', 'https://lattutop.com/cdn/shop/files/3_4.png?v=1785618068&width=533', ARRAY['https://lattutop.com/cdn/shop/files/FRONT_d89edfe9-6f6c-469b-a0ac-b54b402e1141.png?v=1785678687&width=900', 'https://lattutop.com/cdn/shop/files/3_4.png?v=1785618068&width=900', 'https://lattutop.com/cdn/shop/files/SIDE.png?v=1785617267&width=900', 'https://lattutop.com/cdn/shop/files/BACK.png?v=1785617268&width=900'], 'Everyone''s favorite web-slinger, hand-painted down to the web pattern. This is a limited pre-book drop of 10 pieces — production starts once the batch closes, so orders ship a little later than usual.', 'Hand-painted wood', ARRAY['Work Desk', 'Fan Collection', 'Gifting'], true)
